<template><section class="section page"><div class="section-head"><div><p class="eyebrow">EXPLORE THE COLLECTION</p><h1>发现游戏</h1></div><div class="search"><span>⌕</span><input v-model="query" placeholder="搜索游戏..." aria-label="搜索游戏"></div></div><div class="filters"><button v-for="item in categories" :key="item" :class="{active: category === item}" @click="category = item">{{ item }}</button></div><div class="game-grid"><RouterLink v-for="game in filtered" :key="game.id" :to="`/games/${game.id}`" class="game-card"><div class="game-cover" :class="game.color"><span>{{ game.icon }}</span><small>{{ game.type }}</small></div><div class="game-info"><h3>{{ game.title }}</h3><p>{{ game.description }}</p><div><span class="tag">{{ game.category }}</span><span class="play-count">{{ game.plays }} 次游玩</span></div></div></RouterLink></div><p v-if="!filtered.length" class="empty">没有找到匹配的游戏</p></section></template>
<script setup>
import { computed, ref } from 'vue'
const query = ref(''); const category = ref('全部'); const categories = ['全部', '动作', '策略', '休闲', '解谜']
const games = [{ id: 1, title: '星际拓荒者', description: '在无尽宇宙中建立你的新家园。', category: '策略', type: 'STRATEGY', icon: '✦', color: 'cover-purple', plays: '12.4k' }, { id: 2, title: '迷雾之城', description: '解开城市深处被隐藏的谜题。', category: '解谜', type: 'PUZZLE', icon: '◈', color: 'cover-blue', plays: '8.7k' }, { id: 3, title: '像素冲锋', description: '快节奏的像素射击大乱斗。', category: '动作', type: 'ACTION', icon: '✹', color: 'cover-orange', plays: '6.2k' }, { id: 4, title: '悠然小镇', description: '打造你的理想小镇，享受慢生活。', category: '休闲', type: 'CASUAL', icon: '❋', color: 'cover-green', plays: '5.1k' }]
const filtered = computed(() => games.filter(g => (category.value === '全部' || g.category === category.value) && g.title.includes(query.value)))
</script>
